<template><main class="auth-page"><section class="auth-shell wide"><p class="auth-kicker">Communication choices</p><h1>Email preferences</h1><p class="auth-intro">Preferences for {{emailMasked||'your verified email'}}. Essential account and itinerary emails cannot be disabled here.</p><p v-if="message" class="auth-message" :class="{error}">{{message}}</p><div v-if="loading" class="auth-message">Loading preferences...</div><form v-else class="auth-form" @submit.prevent="save"><label v-for="item in options" :key="item.key" class="preference-row"><span class="preference-copy"><strong>{{item.title}}</strong><span>{{item.description}}</span></span><input v-model="values[item.key]" type="checkbox"></label><button class="auth-submit" :disabled="saving">{{saving?'Saving...':'Save preferences'}}</button></form></section></main></template>
<script setup lang="ts">useNoIndex();const route=useRoute();const loading=ref(true);const saving=ref(false);const message=ref('');const error=ref(false);const emailMasked=ref('');const values=reactive<Record<string,boolean>>({POINTS:false,MARKETING:false});const options=[{key:'POINTS',title:'Points and levels',description:'Large point changes and level upgrades.'},{key:'MARKETING',title:'Newsletters and offers',description:'Occasional Lvyv news and selected travel campaigns.'}];const auth=useMemberAuth();const signedToken=computed(()=>typeof route.query.token==='string'?route.query.token:'');onMounted(async()=>{try{const data=signedToken.value?await auth.getPublicPreferences(signedToken.value):await auth.getPreferences();emailMasked.value=data.emailMasked;data.subscriptions.forEach(item=>{if(item.key in values)values[item.key]=item.subscribed})}catch(e){error.value=true;message.value=e instanceof Error?e.message:'Unable to load preferences'}finally{loading.value=false}});const save=async()=>{saving.value=true;error.value=false;try{signedToken.value?await auth.updatePublicPreferences(signedToken.value,values):await auth.updatePreferences(values);message.value='Your email preferences have been saved.'}catch(e){error.value=true;message.value=e instanceof Error?e.message:'Unable to save preferences'}finally{saving.value=false}};</script>
